// Circuit Rescue campaign: adventure objectives and a paused, HTML circuit-workbench dialog.
const level=runtimeScene.getVariables().get('CampaignLevel').getAsNumber();
const LEVELS=[null,
 {title:'Emergency Reboot',gate:'not',rule:'Power the emergency door when input A is OFF.',lesson:'NOT reverses a signal: 0 becomes 1, and 1 becomes 0.',goal:'NOT A',parts:'a fuse, a wire coil and a battery'},
 {title:'Supply Sector',gate:'and',rule:'The cargo lift runs only when A AND B are powered.',lesson:'AND turns the output on only when both inputs are on.',goal:'A AND B',parts:'three cargo components'},
 {title:'Broken Transit',gate:'or',rule:'Restore transit when either generator A OR generator B is on.',lesson:'OR outputs 1 when at least one input is 1.',goal:'A OR B',parts:'three transit components'},
 {title:'Security Lockdown',gate:'xor',rule:'Open the security lock when exactly one input is on.',lesson:'XOR outputs 1 when the two inputs differ.',goal:'A XOR B',parts:'three security components'},
 {title:'Reactor Depths',gate:'nand',rule:'Stop the reactor only when BOTH alarm inputs are active.',lesson:'NAND is an inverted AND. Its output is 0 only for 1,1. NOR is an inverted OR: it outputs 1 only for 0,0.',goal:'A NAND B',parts:'three reactor components'},
 {title:'The Sleeping Giant',gate:'combined',rule:'Start the mecha only when both power cells are active. Use two gates.',lesson:'Compose NAND then NOT to produce AND. Connect the first gate output to the second gate input.',goal:'A AND B',parts:'three mecha startup components'},
 {title:'Siege Corridor',gate:'nor',rule:'Enable the siege weapon only when neither safety alarm is active.',lesson:'NOR outputs 1 only when both inputs are 0. Boarded mecha: hold K for a limited shield; J/X fires the cannon.',goal:'A NOR B',parts:'three cannon components'},
 {title:'Core Guardian',gate:'final',rule:'Disable the guardian shield when exactly one control signal is active.',lesson:'XOR detects different inputs. Solve the terminal, then defeat the guardian. It restores its shield twice; return to the terminal for a new circuit.',goal:'A XOR B',parts:'three shield-control components'}];
const LOCATIONS=['','Emergency Station','Cargo Warehouse','Transit Network','Security Tower','Underground Reactor','Mecha Hangar','Industrial Battlefield','Guardian Core'];
const SYSTEMS=[null,['Emergency lights','Ventilation panel','Station airlock'],['Cargo scanner','Hoist controller','Warehouse exit'],['Track signals','Switching panel','Transit junction'],['Sensor analysis','Security lock','Tower uplink'],['Coolant logic','Alarm inverter','Reactor interlock'],['Power core','Control system','Mecha startup'],['Shield analysis','Weapon repair','Siege controller'],['Outer shield','Core stabilizer','Final shield']];
for(let n=1;n<=8;n++)LEVELS[n].title=LOCATIONS[n];
function taskDefinition(id){
 const base=level===6?'and':level===8?'xor':LEVELS[level].gate;
 const kind=level===8?(id===1?'repair':'build'):['predict','repair','build'][id];
 const type=level===8?['xor','and','nor'][id]:id===1?(level===5?'nor':base):id===2?(level===5?'nand-only-and':LEVELS[level].gate):base;
 const three=kind==='predict'&&level>=5;
 const rule=three?'Keep cooling on while power and safety are on and no fault is detected.':type==='nand-only-and'?'Build an AND circuit using only NAND gates. Use both sockets.':type==='combined'?'Use NAND followed by NOT to start the mecha when both power cells are on. Use both sockets.':kind==='repair'?'Replace the faulty chip and repair the broken wire.':kind==='predict'?'Find the output for each input combination.':'Build a circuit that follows the '+type.toUpperCase()+' rule.';
 const lessons={"not":"NOT gives the opposite result. An active input turns the output off.","and":"AND turns the output on only when both inputs are on.","or":"OR turns the output on when at least one input is on.","xor":"XOR turns the output on when the two inputs are different.","nand":"NAND turns the output off only when both inputs are on.","nor":"NOR turns the output on only when both inputs are off.","combined":"NAND followed by NOT works like AND. Both inputs must be on."};
 return{id,title:SYSTEMS[level][id],kind,type,three,requiredParts:id+1,rule,lesson:three?'Power and safety must be on. The fault signal must be off.':type==='nand-only-and'?'Connect both inputs of the second NAND to the first output. This reverses the first result and creates AND.':lessons[type]};
}
if(!level)return;
const O=n=>runtimeScene.getObjects(n),first=n=>O(n)[0],input=runtimeScene.getGame().getInputManager();
let c=runtimeScene.__campaign;
if(!c||runtimeScene.getTimeManager().isFirstFrame()){
 c=runtimeScene.__campaign={level,definition:LEVELS[level],tasks:[0,1,2].map(taskDefinition),completed:[false,false,false],boards:{},editorHistories:{},activeTerminalId:2,solved:false,mecha:level>=7,boarded:level>=7,eWas:false,bossPhase:0,pendingDamage:0};
 const globals=runtimeScene.getGame().getVariables();globals.get('CRResumeLevel').setNumber(level);
 for(const term of O('MissionTerminal'))term.setAnimationName('Off');
 if(level>=7){c.boss={hp:level===7?24:60,max:level===7?24:60,shield:true,attackAt:2,flashUntil:0,dead:false};}
}
