 if(game.coins<task.requiredParts){game.message='Find '+task.requiredParts+' components for '+task.title+'.';game.messageUntil=game.time+4;return;}
 c.activeTerminalId=id;const s=spec(id),fresh=!c.boards[id],m=c.boards[id]??model(s);c.boards[id]=m;c.board=m;c.currentSpec=s;
 if(fresh&&task.kind==='repair'){m.set(34,s.allowed.find(g=>g!==s.type&&g!=='not')??'buffer');m.connect('A.out','g34.a');if(!s.unary)m.connect('g34.out','Y.in');}
